"""一次性离线核验 v65；不构建、不重跑 LP。"""
import collections, copy, datetime, gzip, hashlib, json, math, re, statistics, subprocess, sys, zipfile
from pathlib import Path
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "knowledge/experiments/data/2026-10-12-halpern-ipm"
PLAN_SHA = "38c989566dd18b5425305fce327fb28e9c56dd022f037f36f49399b60905d340"
FIELDS = ("ipm_extended_krylov_attempts", "ipm_extended_krylov_successes",
          "ipm_homogeneous_scalar_checks", "ipm_homogeneous_scalar_rejections")
SCALAR_FIELDS = FIELDS[2:]
WEIGHTED_FIELDS = ("ipm_weighted_krylov_steps", "ipm_refinement_steps", "ipm_homogeneous_constant_repairs")
COMPAT = ("compatibility-development", "compatibility-probe")
STAGES = (*COMPAT, "development", "probe", "netlib", "highs")
ALLOWED = {"optimal": (0, "resolved"), "empty": (0, "resolved"), "infeasible": (0, "resolved"),
    "unbounded": (0, "resolved"), "verification_failed": (3, "verification_failed"),
    "time_limit": (4, "incomplete"), "iteration_limit": (4, "incomplete"), "numerical_error": (4, "incomplete")}

def require(condition, message):
    if not condition:
        raise AssertionError(message)

def strict(text):
    def pairs(values):
        result = {}
        for key, value in values:
            require(key not in result, "JSON 重复键")
            result[key] = value
        return result
    def number(text):
        value = float(text)
        require(math.isfinite(value), "JSON 非有限浮点")
        return value
    def invalid(text):
        raise ValueError("JSON 非有限常量：" + text)
    return json.loads(text, object_pairs_hook=pairs, parse_float=number, parse_constant=invalid)

def read(path):
    return strict(Path(path).read_text(encoding="utf-8"))

def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def finite(value):
    return type(value) in (int, float) and math.isfinite(value)

def same(a, b):
    if type(a) is bool or type(b) is bool:
        return type(a) is type(b) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[key], b[key]) for key in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def flags(arguments):
    require(len(arguments) % 2 == 0, "参数必须成对")
    result = dict(zip(arguments[::2], arguments[1::2]))
    require(len(result) * 2 == len(arguments) and all(key.startswith("--") for key in result), "重复或非法参数")
    return result

def weighted_valid(report, backend, mode):
    if not isinstance(report, dict) or set(WEIGHTED_FIELDS) - report.keys():
        return False
    w, r, repairs = (report[key] for key in WEIGHTED_FIELDS)
    if backend != "ipm":
        return w is None and r is None and repairs is None
    if any(type(value) is not int or value < 0 or value > (1 << 63)-1 for value in (w, r, repairs)):
        return False
    ceiling = min(r, repairs * 96) if mode == "homogeneous_extended" else 0 if mode == "homogeneous_repair" else r
    return w <= ceiling


def valid_counts(report, version, backend, mode):
    if not weighted_valid(report, backend, mode):
        return False
    present = [key in report for key in FIELDS]
    if version == 57 and not any(present):
        return True
    if not all(present):
        return False
    values = [report[key] for key in FIELDS]
    if backend != "ipm":
        return all(value is None for value in values)
    if not all(type(value) is int and 0 <= value <= 9223372036854775807 for value in values):
        return False
    attempts, successes, checks, rejections = values
    return successes <= attempts and rejections <= checks and (
        mode == "homogeneous_extended" or all(value == 0 for value in values))

def valid_process(row):
    report = row.get("report")
    if row.get("error") is not None or not isinstance(report, dict) or type(row.get("returncode")) is not int:
        return False
    if type(report.get("schema_version")) is not int or report["schema_version"] != 1:
        return False
    status = report.get("status")
    if not isinstance(status, str) or status not in ALLOWED or row.get("status") != status:
        return False
    if (row["returncode"], row.get("classification")) != ALLOWED[status]:
        return False
    times = report.get("timings")
    if not isinstance(times, dict) or not all(finite(times.get(key)) and times[key] >= 0 for key in ("read_seconds", "solve_seconds", "verification_seconds", "total_seconds")):
        return False
    backend, options = report.get("backend"), report.get("options")
    if backend not in ("ipm", "highs") or not isinstance(options, dict):
        return False
    ipm = options.get("ipm")
    mode = ipm.get("linear_accuracy") if isinstance(ipm, dict) else None
    if backend == "ipm" and not isinstance(mode, str) or not weighted_valid(report, backend, mode):
        return False
    return finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 0 and finite(row.get("numerical_seconds")) and row["numerical_seconds"] >= 0

def limited(row):
    return row.get("error") == "wall_timeout" or (row.get("report") or {}).get("status") == "time_limit" or (finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 35) or (finite(row.get("numerical_seconds")) and row["numerical_seconds"] > 5)

def trajectory(a, b):
    reports = copy.deepcopy([a.get("report"), b.get("report")])
    for report in reports:
        if isinstance(report, dict):
            for key in ("timings", "backend_version", *FIELDS):
                report.pop(key, None)
    equal = same(*reports) and a.get("returncode") == b.get("returncode") and a.get("error") == b.get("error")
    valid, budget = valid_process(a) and valid_process(b), limited(a) or limited(b)
    return {"equal": equal, "valid_processes": valid, "budget_limited": budget,
        "category": "invalid_process" if not valid else "budget_limited" if budget else "equal" if equal else "different"}

def self_check():
    cases = [({}, 57, "ipm", "homogeneous_repair", True), ({}, 65, "ipm", "homogeneous_extended", False)]
    for values, mode, good in (
        ((0, 0, 0, 0), "homogeneous_repair", True),
        ((1, 1, 3, 2), "homogeneous_extended", True),
        ((1, 0, 2, 2), "homogeneous_extended", True),
        ((0, 0, 0, 0), "homogeneous_extended", True),
        (((1 << 63) - 1,) * 4, "homogeneous_extended", True),
        ((1, 2, 0, 0), "homogeneous_extended", False),
        ((0, 0, 1, 2), "homogeneous_extended", False)):
        cases.append((dict(zip(FIELDS, values)), 65, "ipm", mode, good))
    for field in FIELDS:
        invalid_mode = dict.fromkeys(FIELDS, 0)
        invalid_mode[field] = 1
        cases.append((invalid_mode, 65, "ipm", "homogeneous_repair", False))
        for value in (True, False, -1, 1.0, 1 << 63):
            invalid = dict.fromkeys(FIELDS, 0)
            invalid[field] = value
            cases.append((invalid, 65, "ipm", "homogeneous_extended", False))
        partial = dict.fromkeys(FIELDS, 0)
        del partial[field]
        cases.append((partial, 65, "ipm", "homogeneous_extended", False))
    cases += [(dict.fromkeys(FIELDS, None), 65, "highs", "homogeneous_extended", True),
              (dict.fromkeys(FIELDS, 0), 65, "highs", "homogeneous_extended", False),
              ({FIELDS[0]: 0}, 57, "ipm", "homogeneous_repair", False)]
    for report, version, backend, mode, good in cases:
        value = {**dict.fromkeys(WEIGHTED_FIELDS, 0 if backend == "ipm" else None), **report}
        require(valid_counts(value, version, backend, mode) is good, "计数反例")
    status_cases = 0
    for status in ALLOWED:
        for field in FIELDS:
            invalid = {"status": status, **dict.fromkeys(FIELDS, 0), **dict.fromkeys(WEIGHTED_FIELDS, 0)}
            invalid[field] = True
            require(not valid_counts(invalid, 65, "ipm", "homogeneous_extended"), "所有状态均拒绝非法计数")
            status_cases += 1
    row = {"error": None, "classification": "incomplete", "status": "numerical_error", "returncode": 4,
        "report": {"schema_version": 1, "status": "numerical_error", "backend_version": "ipm-cpu-0.47.0",
            "backend": "ipm", "options": {"ipm": {"linear_accuracy": "homogeneous_repair"}}, **dict.fromkeys(WEIGHTED_FIELDS, 0),
            "timings": {"read_seconds": 0, "solve_seconds": 1, "verification_seconds": 0, "total_seconds": 1}}, "numerical_seconds": 1, "elapsed_wall_seconds": 2}
    modern = copy.deepcopy(row)
    modern["report"].update(backend_version="ipm-cpu-0.52.0", **dict.fromkeys(FIELDS, 0))
    require(trajectory(row, modern)["category"] == "equal", "兼容排除字段")
    budget = copy.deepcopy(row)
    budget["status"] = budget["report"]["status"] = "time_limit"
    require(trajectory(row, budget)["category"] == "budget_limited", "合法预算分叉")
    invalids = []
    for status in ("bogus", None, True):
        bad = copy.deepcopy(row)
        bad["status"] = bad["report"]["status"] = status
        invalids.append(bad)
    for key, value in (("returncode", False), ("returncode", -1073741819), ("error", "wall_timeout"), ("numerical_seconds", None)):
        bad = copy.deepcopy(row)
        bad[key] = value
        invalids.append(bad)
    for bad in invalids:
        require(trajectory(bad, budget)["category"] == "invalid_process", "invalid 必须优先于预算")
    require(not same({"x": True}, {"x": 1}), "布尔不得冒充整数")
    try:
        strict('{"x":1,"x":2}')
    except AssertionError:
        pass
    else:
        raise AssertionError("重复 JSON 键未拒绝")
    weighted_cases = []
    for values, mode, expected in (((0,0,0), "homogeneous_extended", True),
        ((0,0,1), "homogeneous_extended", True), ((96,96,1), "homogeneous_extended", True),
        ((192,200,2), "homogeneous_extended", True), ((97,97,1), "homogeneous_extended", False),
        ((1,0,1), "homogeneous_extended", False), ((1,1,0), "homogeneous_extended", False),
        ((1,1,1), "homogeneous_repair", False), ((0,7,3), "homogeneous_repair", True),
        (((1 << 63)-1,)*3, "homogeneous_extended", True)):
        weighted_cases.append((dict(zip(WEIGHTED_FIELDS,values)), "ipm", mode, expected))
    for mode in ("blockwise_weighted", "blockwise_forcing_weighted", "full_newton", "bounded_newton"):
        weighted_cases.append((dict(zip(WEIGHTED_FIELDS,(2,3,0))), "ipm", mode, True))
    for field in WEIGHTED_FIELDS:
        for value in (True, False, -1, 1.0, 1 << 63, None):
            invalid = dict.fromkeys(WEIGHTED_FIELDS,0); invalid[field] = value
            weighted_cases.append((invalid,"ipm","homogeneous_extended",False))
        invalid=dict.fromkeys(WEIGHTED_FIELDS,0); del invalid[field]
        weighted_cases.append((invalid,"ipm","homogeneous_extended",False))
    weighted_cases += [(dict.fromkeys(WEIGHTED_FIELDS,None),"highs",None,True),
        (dict.fromkeys(WEIGHTED_FIELDS,0),"highs",None,False),
        ({key:None for key in WEIGHTED_FIELDS[1:]},"highs",None,False)]
    for value,backend,mode,expected in weighted_cases:
        require(weighted_valid(value,backend,mode) is expected,"独立加权账本反例")
    weighted_status = weighted_budget = 0
    for status,(code,classification) in ALLOWED.items():
        for value,backend,mode,expected in weighted_cases:
            if backend != "ipm" or expected: continue
            bad=copy.deepcopy(row); bad.update(status=status,returncode=code,classification=classification)
            bad["report"].update(status=status,**dict.fromkeys(FIELDS,0))
            bad["report"]["options"]["ipm"]["linear_accuracy"] = mode
            for key in WEIGHTED_FIELDS: bad["report"].pop(key)
            bad["report"].update(value)
            require(not valid_counts(bad["report"],65,"ipm",mode),"每种结束状态均核weighted")
            weighted_status += 1
            require(trajectory(bad,budget)["category"] == "invalid_process","加权坏账本优先于预算")
            weighted_budget += 1
    return {"passed": True, "count_cases": len(cases), "all_status_count_cases": status_cases,
        "trajectory_cases": 2 + len(invalids), "invalid_budget_counterexamples": len(invalids),
        "json_and_type_cases": 2, "weighted_count_cases": len(weighted_cases),
        "weighted_all_status_cases": weighted_status, "weighted_invalid_budget_cases": weighted_budget, "lp_runs": 0}

def expected_options(backend, mode):
    return {"backend": backend, "time_limit": 5, "threads": 1, "seed": 0, "mip_relative_gap": 0.0001, "pdlp": None,
        "ipm": None if backend == "highs" else {"method": "homogeneous", "max_iterations": 200, "scaling_passes": 5, "objective_scaling": False, "eliminate_singletons": True, "dynamic_regularization": False, "equilibrate_kkt": True, "linear_accuracy": mode, "central_corrections": 0, "direction_retries": 0, "krylov_history_size": 0, "linear_solver": "normal_cholmod", "eliminate_fixed_variables": True, "presolve_singleton_rows": False, "eliminate_presolved_fixed_variables": False, "inexact_prefilter": False},
        "highs": {"solver": "choose", "run_crossover": "on", "presolve": "choose"} if backend == "highs" else None,
        "tolerances": {"feasibility_absolute": 1e-7, "feasibility_relative": 1e-9, "integrality": 1e-6, "objective_absolute": 1e-7, "objective_relative": 1e-9}}

def numerical_flags(backend, mode):
    result = {"--backend": backend, "--time-limit": "5.0", "--threads": "1", "--seed": "0", "--mip-gap": "0.0001"}
    if backend == "highs":
        result.update({"--highs-solver": "choose", "--highs-crossover": "on", "--highs-presolve": "choose"})
    else:
        result.update({"--iteration-limit": "200", "--scaling-passes": "5", "--ipm-method": "homogeneous", "--ipm-linear-accuracy": mode, "--ipm-linear-solver": "normal_cholmod", "--ipm-direction-retries": "0", "--ipm-objective-scaling": "off", "--ipm-singleton-elimination": "on", "--ipm-dynamic-regularization": "off", "--ipm-kkt-equilibration": "on", "--ipm-fixed-variable-elimination": "on", "--ipm-singleton-presolve": "off", "--ipm-presolve-fixed-elimination": "off", "--ipm-krylov-history-size": "0", "--ipm-central-corrections": "0", "--ipm-inexact-prefilter": "off"})
    return result

def sgm(values):
    return math.expm1(sum(math.log1p(value / 10.0) for value in values) / len(values)) * 10.0

def audit_summary(summary, rows, models, repeats, sides):
    require(summary["model_count"] == len(models) and summary["repeats"] == repeats and summary["run_count"] == len(rows), "汇总数量")
    require(summary["quality_pass_count"] == sum(row["quality_pass"] for row in rows), "总达标数")
    result = {}
    for side in sides:
        selected = [row for row in rows if row["requested_variant"] == side]
        counts = collections.Counter(row["model_index"] for row in selected if row["quality_pass"])
        expected = {"run_count": len(selected), "quality_pass_count": sum(row["quality_pass"] for row in selected),
            "all_repeats_quality_pass_model_count": sum(counts[model["model_index"]] == repeats for model in models),
            "quality_failure_counts": dict(collections.Counter(row["quality_failure"] for row in selected if not row["quality_pass"])),
            "status_counts": dict(collections.Counter(row["status"] for row in selected)),
            "penalized_wall_sgm10_seconds": sgm([row["quality_penalized_wall_seconds"] for row in selected]),
            "penalized_numerical_sgm10_seconds": sgm([row["quality_penalized_numerical_seconds"] for row in selected]),
            "numerical_budget_exceeded_count": sum(row["numerical_budget_exceeded"] for row in selected),
            "wall_budget_exceeded_count": sum(row["wall_budget_exceeded"] for row in selected)}
        require(same(summary["variants"][side], expected), "独立重算每侧 SGM/覆盖/状态")
        result[side] = expected
    require(len(summary["models"]) == len(models), "逐例汇总数量")
    both, winners = 0, collections.Counter()
    for model, item in zip(models, summary["models"]):
        groups = {side: [row for row in rows if row["requested_variant"] == side and row["model_index"] == model["model_index"]] for side in sides}
        require(all(len(group) == repeats for group in groups.values()), "逐例重复次数")
        counts = {side: sum(row["quality_pass"] for row in group) for side, group in groups.items()}
        require((item["input"], item["sha256"], item["model_index"]) == (model["input"], model["sha256"], model["model_index"]), "逐例身份")
        require(item["quality_pass_counts"] == counts, "逐例达标次数")
        complete = all(value == repeats for value in counts.values())
        require(item["all_repeats_quality_pass"] is complete, "双方完整达标标志")
        if complete:
            both += 1
            for kind, field in (("wall", "elapsed_wall_seconds"), ("numerical", "numerical_seconds")):
                median = {side: statistics.median(row[field] for row in group) for side, group in groups.items()}
                ranges = {side: [min(row[field] for row in group), max(row[field] for row in group)] for side, group in groups.items()}
                require(item["median_" + kind + "_seconds"] == median and item[kind + "_range_seconds"] == ranges, "逐例中位数/区间")
                ratio = median[sides[0]] / median[sides[1]] if median[sides[1]] > 0 else None
                require(item[kind + "_speedup_reference_over_candidate"] == ratio, "逐例速度比")
                if kind == "wall":
                    winner = "tie" if median[sides[0]] == median[sides[1]] else min(median, key=median.get)
                    require(item["wall_winner"] == winner, "逐例墙钟胜者")
                    winners[winner] += 1
        else:
            require(all(item[key] is None for key in ("median_wall_seconds", "median_numerical_seconds", "wall_range_seconds", "numerical_range_seconds", "wall_speedup_reference_over_candidate", "numerical_speedup_reference_over_candidate", "wall_winner")), "失败样本不得计算成功速度")
    require(summary["both_variants_all_repeats_pass_count"] == both and summary["wall_winner_counts"] == dict(winners), "整体成对统计")
    return result

def audit_wrapped_attempts(prefix, script, arguments):
    paths = sorted(DATA.glob(prefix + "-attempt[0-9]*.json"),
        key=lambda path: int(re.search(r"attempt([0-9]+)",path.name).group(1)))
    require(bool(paths) and [int(re.search(r"attempt([0-9]+)",p.name).group(1)) for p in paths] ==
        list(range(1,len(paths)+1)), "外层执行attempt完整连续：" + prefix)
    result = []; previous = datetime.datetime.fromisoformat(read(DATA/"v65-plan.json")["created_at_utc"])
    wrapper = ROOT/".tools/v65-attempt-inline.py"
    for path in paths:
        record = read(path)
        begin,end = (datetime.datetime.fromisoformat(record[key]) for key in ("started_at_utc","completed_at_utc"))
        require(begin >= previous and end >= begin and finite(record["elapsed_seconds"]) and record["elapsed_seconds"] >= 0,
            "真实调用前开始与调用后完成时刻")
        previous = end
        require(type(record["returncode"]) is int and record["command"] == [sys.executable,str(script),*arguments],
            "外层实际命令与退出码")
        require(hashlib.sha256(record["source"].encode("utf-8")).hexdigest() == record["source_sha256"] and
            hashlib.sha256(record["wrapper_source"].encode("utf-8")).hexdigest() == record["wrapper_sha256"] == sha(wrapper),
            "按原bytes保存脚本和wrapper，CRLF属于原身份")
        result.append({"attempt":path.name,"attempt_sha256":sha(path),"started_at_utc":record["started_at_utc"],
            "completed_at_utc":record["completed_at_utc"],"returncode":record["returncode"],
            "source_sha256":record["source_sha256"],"wrapper_sha256":record["wrapper_sha256"],
            "stdout":record["stdout"],"stderr":record["stderr"]})
    require(result[-1]["returncode"] == 0 and result[-1]["stderr"] == "" and
        result[-1]["source_sha256"] == sha(script), "最后一次成功执行对应当前已锁定脚本")
    return result


def audit_build_history(plan, current):
    paths = sorted(DATA.glob("v65-build-attempt[0-9]*.json"),
        key=lambda path: int(re.search(r"attempt([0-9]+)", path.name).group(1)))
    require(bool(paths), "至少保留一次实际构建记录")
    numbers = [int(re.search(r"attempt([0-9]+)", path.name).group(1)) for path in paths]
    require(numbers == list(range(1, len(paths)+1)), "构建尝试必须完整连续")
    attempts = [read(path) for path in paths]
    require(attempts[-1]["returncode"] == 0 and attempts[-1]["error"] is None, "最终冻结必须来自成功构建")
    plan_time = datetime.datetime.fromisoformat(plan["created_at_utc"])
    previous_time = plan_time
    history = []
    def resolve(value):
        path = Path(value)
        path = path if path.is_absolute() else DATA / path
        require(path.resolve().is_relative_to(ROOT) and path.is_file(), "构建证据必须真实保留在工作区")
        return path
    for number, path, attempt in zip(numbers, paths, attempts):
        require(attempt["plan_sha256"] == PLAN_SHA and attempt["baseline_check_sha256"] == plan["baseline_check"]["sha256"] and
            attempt["lp_runs"] == 0 and type(attempt["build_invocation_attempted"]) is bool, "构建驱动范围与计划")
        driver_start = datetime.datetime.fromisoformat(attempt["driver_started_at_utc"])
        ended = datetime.datetime.fromisoformat(attempt["completed_at_utc"])
        require(driver_start >= previous_time and ended >= driver_start, "构建驱动实际开始完成顺序")
        require(hashlib.sha256(attempt["driver_source"].encode("utf-8")).hexdigest() == attempt["driver_sha256"],
            "构建驱动原字节源码留存")
        if not attempt["build_invocation_attempted"]:
            require(number != len(paths) and attempt["returncode"] is None and attempt["started_at_utc"] is None and
                attempt["error"] is not None, "构建前预检失败单独保留，不能冒充实际测试")
            history.append({"attempt":path.name,"attempt_sha256":sha(path),"returncode":None,
                "precheck_failed":True,"started_at_utc":None,"completed_at_utc":attempt["completed_at_utc"]})
            previous_time = ended
            continue
        require(attempt["sources_unchanged"] is True and type(attempt["returncode"]) is int,
            "实际构建退出码与来源稳定性")
        when = datetime.datetime.fromisoformat(attempt["started_at_utc"])
        require(driver_start <= when <= ended and when >= previous_time, "先冻结计划，再依序构建")
        previous_time = ended
        require(set(attempt["source_sha256"]) == set(plan["changed_source_files"]), "每次构建十来源集合")
        require(set(attempt["all_sources_sha256"]) == set(current["files"]) and
            all(attempt["all_sources_sha256"][name] == value for name,value in attempt["source_sha256"].items()),
            "每次构建95来源全集与十项差集对应")
        require(hashlib.sha256(attempt["driver_source"].encode("utf-8")).hexdigest() == attempt["driver_sha256"],
            "构建驱动完整源码留存")
        item = {"attempt": path.name, "attempt_sha256": sha(path), "returncode": attempt["returncode"],
            "source_sha256": attempt["source_sha256"], "all_sources_sha256": attempt["all_sources_sha256"],
            "started_at_utc":attempt["started_at_utc"],"completed_at_utc":attempt["completed_at_utc"]}
        require("build_log" in attempt and "ctest_detail" in attempt and "source_snapshot" in attempt,
            "每次构建日志、CTest明细存在性及来源快照必须保留")
        log_path = resolve(attempt["build_log"])
        detail_path = resolve(attempt["ctest_detail"]) if attempt["ctest_detail"] is not None else None
        if number == len(paths):
            require(attempt["source_sha256"] == {name: current["files"][name] for name in plan["changed_source_files"]},
                "最终成功构建十来源对应冻结成员")
            require(attempt["all_sources_sha256"] == current["files"] and
                sha(log_path) == sha(DATA / "iteration-ipm-v65-build.log") and detail_path is not None and
                sha(detail_path) == sha(DATA / "iteration-ipm-v65-ctest-detail.log"), "末构建95来源与冻结原始日志完全相同")
        require(sha(log_path) == attempt["log_sha256"], "实际构建日志身份")
        item.update(log=str(log_path), log_sha256=sha(log_path), ctest_detail=str(detail_path) if detail_path else None,
            ctest_detail_sha256=sha(detail_path) if detail_path else None)
        if detail_path is not None:
            require(sha(detail_path) == attempt["ctest_detail_sha256"], "实际CTest明细身份")
        else:
            require(attempt["returncode"] != 0 and attempt["ctest_detail_sha256"] is None,
                "未产生CTest日志只允许未成功构建，不能伪造通过")
        if "source_snapshot" in attempt:
            source_path = resolve(attempt["source_snapshot"])
            require(sha(source_path) == attempt["source_snapshot_sha256"], "构建来源快照身份")
            with zipfile.ZipFile(source_path) as archive:
                names = archive.namelist()
                require(len(names) == len(set(names)) == 95 and set(names) == set(current["files"]),
                    "历史源码快照95个成员完整")
                require({name: hashlib.sha256(archive.read(name)).hexdigest() for name in names} ==
                    attempt["all_sources_sha256"], "历史95源码快照逐字对应")
            item.update(source_snapshot=str(source_path), source_snapshot_sha256=sha(source_path))
        if attempt["returncode"] == 0:
            require(attempt["error"] is None and attempt["ctest_detail_fresh"] is True and detail_path is not None and b"100% tests passed out of 18" in log_path.read_bytes() and
                detail_path.read_bytes().count(b"Test Passed.") == 18, "成功构建实际18测试通过")
        else:
            require(number != len(paths), "失败构建不能被冻结")
        history.append(item)
    require(history[-1]["log_sha256"] == current["logs"]["iteration-ipm-v65-build.log"], "冻结日志对应末成功尝试")
    return {"attempt_count": len(paths), "attempts": history,
        "returncodes": [attempt["returncode"] for attempt in attempts],
        "failed_attempts": sum(attempt["returncode"] != 0 for attempt in attempts), "final_sources_match_frozen": True}


def compare_v62_non_timing(groups, plan, current, ancestor_identity):
    # 旧 v62 只提供排除时间的报告对照，不能参与本轮速度门槛。
    excluded = ("timings", "backend_version")
    result = {"schema": 1, "created_at_utc": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "plan_sha256": PLAN_SHA, "ancestor_identity_sha256": plan["implementation_ancestor"]["identity_sha256"],
        "candidate_identity_sha256": sha(DATA / "ipm-v65-identity.json"),
        "excluded_report_fields": list(excluded), "pair_count": 0, "equal_pairs": 0, "different_pairs": 0,
        "scalar_checked_pairs": 0, "scalar_rejected_pairs": 0,
        "no_rejection_equal_pairs": 0, "no_rejection_different_pairs": 0, "pairs": [], "sources": {},
        "limits": ["只比较相同公开输入、重复序号及数值选项的冻结候选报告；全部时间字段排除。",
            "这是事后跨轮路径对照，不是本轮速度对照，不参与扩集门槛，也不新增LP运行。",
            "报告差异仅反映已保存的最终状态和计数；没有逐内步轨迹时不能定位每次候选或当前工作点。",
            "本轮未新增内部捕获；不能从累计计数差异单独归因某个中间候选，也不把终点相同视为全过程相同。"],
        "lp_runs": 0}
    if "development" not in groups:
        result["scope"] = "兼容阶段未通过，本轮没有性能候选记录，事后对照不适用。"
        return result
    ancestor = plan["implementation_ancestor"]
    old_identity_path = DATA / ancestor["identity_file"]
    require(sha(old_identity_path) == ancestor["identity_sha256"], "事后对照祖先身份")
    old_verification = read(DATA / "v62-verification.json")
    require(old_verification["passed"] is True and
        old_verification["identity_sha256"] == ancestor["identity_sha256"] and
        old_verification["plan_sha256"] == ancestor_identity["plan_sha256"], "旧核验来源链")
    result["sources"]["v62-verification.json"] = sha(DATA / "v62-verification.json")
    require(sha(DATA / "v62-plan.json") == ancestor_identity["plan_sha256"], "旧计划身份")
    old_plan = read(DATA / "v62-plan.json")
    require(old_plan["candidate_accuracy"] == plan["candidate_accuracy"] == "homogeneous_extended" and
        old_plan["sets"] == plan["sets"] and old_plan["shared_ipm"] == plan["shared_ipm"], "跨轮同数值选项和输入")
    for stage in ("development", "probe"):
        require(stage in groups, "性能初始两阶段完整后才作事后对照")
        new_manifest, _, new_rows = groups[stage]
        raw_path = DATA / ("v62-" + stage + "-runs.jsonl.gz")
        require(sha(raw_path) == old_verification["stages"][stage]["raw_sha256"], "旧性能原始记录身份")
        old_rows = [strict(line) for line in gzip.decompress(raw_path.read_bytes()).splitlines()]
        old_manifest = read(DATA / ("v62-" + stage + "-manifest.json"))
        require(old_manifest["models"] == new_manifest["models"] == plan["sets"][stage]["models"] and
            old_manifest["repeats"] == new_manifest["repeats"] == 3, "跨轮模型与重复数")
        old_variant = old_manifest["candidate_variant"]
        require(old_manifest["solvers"][old_variant] == {"path": str(ROOT / ".tools/solver-ipm-v62.exe"),
            "sha256": ancestor_identity["solver_sha256"], "hash_error": None}, "旧候选程序身份")
        require(len(old_rows) == len(new_rows) == len(plan["sets"][stage]["models"]) * 6,
            "跨轮原始记录数量一致")
        def keyed(rows, variant):
            selected = {}
            for row in rows:
                if row["requested_variant"] != variant:
                    continue
                key = (row["input"], row["model_sha256"], row["repetition"])
                require(key not in selected, "事后对照配对键不得重复")
                selected[key] = row
            return selected
        older = keyed(old_rows, old_variant)
        newer = keyed(new_rows, new_manifest["candidate_variant"])
        require(older.keys() == newer.keys() and len(older) == len(plan["sets"][stage]["models"]) * 3,
            "事后对照输入哈希与重复序号完整配对")
        result["sources"][raw_path.name] = sha(raw_path)
        result["sources"]["v65-" + stage + "-runs.jsonl.gz"] = sha(DATA / ("v65-" + stage + "-runs.jsonl.gz"))
        for key in sorted(older, key=lambda item: (item[0], item[2])):
            old_row, new_row = older[key], newer[key]
            old_report, new_report = old_row["report"], new_row["report"]
            require(valid_process(old_row) and same(strict(old_row["stdout"]), old_report), "旧候选进程和原报告")
            require(old_report["backend"] == "ipm" and old_report["backend_version"] == "ipm-cpu-0.50.0" and
                old_report["input"] == key[0], "旧候选报告身份")
            require(all(old_row[field] == ancestor_identity["solver_sha256"] for field in
                ("solver_sha256_before", "solver_sha256_after", "frozen_solver_sha256")), "旧候选程序前后身份")
            require(all(old_row[field] == key[1] for field in
                ("model_sha256", "model_sha256_after", "frozen_model_sha256")), "旧候选输入前后身份")
            require(same(old_report["options"], expected_options("ipm", "homogeneous_extended")) and
                same(old_report["options"], new_report["options"]), "跨轮完整实际选项和容差一致")
            require(old_row["command"][:3] == [str(ROOT / ".tools/solver-ipm-v62.exe"), "solve", key[0]] and
                flags(old_row["command"][3:]) == numerical_flags("ipm", "homogeneous_extended"), "旧候选实际参数")
            require(valid_counts(old_report, 62, "ipm", "homogeneous_extended"),
                "旧v62完整四计数同样严格校验，不排除标量计数")
            filtered = [{field: value for field, value in report.items() if field not in excluded}
                        for report in (old_report, new_report)]
            differences = sorted(field for field in filtered[0].keys() | filtered[1].keys()
                if field not in filtered[0] or field not in filtered[1] or not same(filtered[0][field], filtered[1][field]))
            process_equal = old_row["returncode"] == new_row["returncode"] and old_row["error"] == new_row["error"]
            equal = not differences and process_equal
            checked, rejected = (new_report[field] for field in SCALAR_FIELDS)
            work_fields = ("status", "message", "ipm_iterations", "ipm_factorizations", "ipm_refinement_steps",
                "ipm_weighted_krylov_steps",
                "ipm_homogeneous_constant_solves", "ipm_homogeneous_direction_solves",
                "ipm_homogeneous_constant_repairs", "ipm_homogeneous_constant_repair_successes", *FIELDS)
            result["pairs"].append({"stage": stage, "input": key[0], "input_sha256": key[1], "repetition": key[2],
                "equal": equal, "different_report_fields": differences, "exit_and_error_equal": process_equal,
                "scalar_checks": checked, "scalar_rejections": rejected,
                "v62": {field: old_report.get(field) for field in work_fields},
                "v65": {field: new_report.get(field) for field in work_fields}})
            result["pair_count"] += 1
            result["equal_pairs" if equal else "different_pairs"] += 1
            result["scalar_checked_pairs"] += int(checked > 0)
            result["scalar_rejected_pairs"] += int(rejected > 0)
            if rejected == 0:
                result["no_rejection_equal_pairs" if equal else "no_rejection_different_pairs"] += 1
    require(result["pair_count"] == 51, "11+6输入各三次事后候选对子")
    return result


def main():
    checks = self_check()
